import { useId } from "react";
import type { ReactElement } from "react";
import "./ChipFilter.css";

export interface ChipOption<T extends string = string> {
  value: T;
  label: string;
}

export interface ChipFilterProps<T extends string = string> {
  label: string;
  options: readonly ChipOption<T>[];
  selected: readonly T[];
  onToggle: (value: T) => void;
}

export function ChipFilter<T extends string = string>({
  label,
  options,
  selected,
  onToggle,
}: ChipFilterProps<T>): ReactElement {
  const labelId = useId();

  return (
    <div role="group" aria-labelledby={labelId} className="chip-filter">
      <span id={labelId} className="chip-filter__label">
        {label}
      </span>
      {options.map((option) => (
        <button
          key={option.value}
          type="button"
          className="chip-filter__chip"
          aria-pressed={selected.includes(option.value)}
          onClick={() => onToggle(option.value)}
        >
          {option.label}
        </button>
      ))}
    </div>
  );
}
```

```css
.chip-filter {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: clamp(0.5rem, 1vw, 0.75rem);
  font: inherit;
}

.chip-filter__label {
  color: var(--muted);
  font-size: clamp(0.8rem, 0.9vw, 0.95rem);
  margin-inline-end: clamp(0.25rem, 0.5vw, 0.5rem);
}

.chip-filter__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.45em;
  padding: 0.4em 0.9em;
  border: 1px solid var(--muted);
  border-radius: 999px;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: clamp(0.85rem, 1vw, 1rem);
  cursor: pointer;
  transition: background-color 150ms ease, border-color 150ms ease;
}

.chip-filter__chip:hover {
  background: var(--myelin-wash);
}

.chip-filter__chip[aria-pressed="true"] {
  background: var(--cresyl-wash);
  border-color: var(--cresyl);
}

.chip-filter__chip[aria-pressed="true"]::before {
  content: "";
  width: 0.5em;
  height: 0.5em;
  border-radius: 50%;
  background: var(--cresyl);
}

:root[data-motion="reduce"] .chip-filter__chip,
@media (prefers-reduced-motion: reduce) {
  .chip-filter__chip {
    transition: none;
  }
}
